                 }
                 Poll::Ready(Err(err)) if err.kind() == std::io::ErrorKind::WouldBlock => {
                     // No more bytes available on the socket to read
+                    continue;
                 }
                 Poll::Ready(Err(err)) => {
                     tracing::error!("failed reading datagram: {}", err);
